function ixKriReturnsView(){return header('Branch KRI returns','Monthly collection, unit accountability, independent review and branch consolidation.',btn('Create reporting cycle','ix-new-cycle','','primary'),'KRI reporting')+riskTabs('indicators')+`<div class="ix-report-tools">${ixCycleSelect()}${link('Branch comparison','reports?view=kri','small')}${btn(icon('download')+' Export accepted values','ix-export-kri','','small')}<div class="grow"></div><span>Definition ${e(ixCycle().definitionVersion)}</span></div>`+ixKriSummary()+ixReturnsTable()+`<details class="panel ix-method"><summary>Metric definitions and reporting rules</summary><div class="pad">${table(['Metric','Near limit','Breach','Basis'],ixCycle().metrics.map(m=>({cells:[e(m.name),`> ${m.warning} ${m.unit}`,`> ${m.limit} ${m.unit}`,e(m.help)]})))}<p>These are internally authored demonstration thresholds, not regulatory limits. The monthly branch workflow is separate from continuous KRI/KCI observations, and does not overwrite them.</p>${link('Continuous indicators','indicators','small')}</div></details>`;}
