function ixCycleView(){const d=S.branchKri.draftCycle;if(!d)return header('Create reporting cycle','Choose a fixed population and period.')+empty('No cycle in preparation','Start a reporting cycle from the KRI workspace.',btn('Start setup','ix-new-cycle','','primary'));const step=d.step;let body='';
 if(step===1)body=`<h2>What will the units report?</h2><p>Use the seeded branch-operations definition. Its three metric definitions and thresholds will be frozen in the cycle.</p><div class="field-grid">${input('name','Cycle name',d.name,'text','data-ix-cycle-draft="name"')}${input('period','Reporting month',d.period,'month','data-ix-cycle-draft="period" max="2026-11"')}</div><div class="mt16">${table(['Metric','Near / breach','Aggregate'],IX_METRICS.map(m=>({cells:[e(m.name),`> ${m.warning} / > ${m.limit} ${m.unit}`,e(m.aggregation)]})))}</div><p>Current-month cycles can collect drafts. Monthly submission opens only after the period ends.</p>`;
 if(step===2)body=`<h2>Who reports, and who reviews?</h2><p>Reporting units are explicit and frozen. Changing the top navigation does not alter this selection.</p><div class="field-grid">${select('owner','Respondent / accountable owner',CS_SEED.people,d.owner,'data-ix-cycle-draft="owner"')}${select('reviewer','Independent reviewer',CS_SEED.people,d.reviewer,'data-ix-cycle-draft="reviewer"')}${select('programId','Program context (optional)',[['','Standalone return'],...S.programs.map(p=>[p.id,p.name])],d.programId,'data-ix-cycle-draft="programId"')}</div><h3 class="mt16">Reporting population</h3><div class="ix-population">${ORG.filter(n=>n.kind==='unit').map(n=>`<label class="checkbox-row"><input type="checkbox" data-ix-population="${n.id}" ${d.population.includes(n.id)?'checked':''}><span>${e(orgName(n.id))}</span></label>`).join('')}</div>`;
 if(step===3)body=`<h2>Review the reporting cycle</h2><div class="ix-confidence"><div><span>Period</span><strong>${e(d.period)}</strong></div><div><span>Expected returns</span><strong>${d.population.length}</strong></div><div><span>Owner / reviewer</span><strong>${e(d.owner)} / ${e(d.reviewer)}</strong></div><div><span>Definition</span><strong>BRANCH-OPS/1.0</strong></div></div><p>${d.population.map(u=>e(orgName(u))).join('<br>')}</p>${notice('The cycle creates expected return slots, not pre-filled or approved results. Unknown data remains visible in reporting coverage.','mini')}`;
 return header('Create KRI reporting cycle','A guided setup for a reusable, version-pinned reporting population.',link('Exit setup','kri-returns'),'KRI setup')+ixWizardSteps(['Definition & period','People & population','Review'],step,'ix-cycle-step')+`<section class="panel ix-wizard"><div class="pad">${body}<div id="ix-cycle-error" role="alert"></div></div><footer>${step>1?btn('Back','ix-cycle-step',`data-step="${step-1}"`):link('Cancel','kri-returns')}<span>Step ${step} of 3</span>${step<3?btn('Continue '+icon('arrow'),'ix-cycle-step',`data-step="${step+1}"`,'primary'):btn('Create reporting cycle','ix-create-cycle','','primary')}</footer></section>`;
}
function ixDetailData(){
 const kind=current.params.get('kind')||'appetite',id=current.params.get('id');let risks=ixRiskRows(),losses=ixLossPeriod(),label='Risks above appetite';
 if(['category','owner','risk'].includes(kind)){risks=risks.filter(r=>(kind==='category'?r.category:kind==='owner'?r.owner:r.id)===id);label=kind==='risk'?(risks[0]?.title||id):id;losses=losses.filter(l=>{const r=S.risks.find(x=>x.id===l.risk);return (r?(kind==='category'?r.category:kind==='owner'?r.owner:r.id):'Unattributed')===id;});}
 else if(kind==='location'){const node=orgNode(id);if(!node||!ixMatch(id))return {label:'Outside the selected scope',risks:[],losses:[],tasks:[],kind};risks=ixRiskRows(id);losses=ixLossPeriod(scopePeriod(),id);label=orgName(id);}
 else if(kind==='appetite'){risks=risks.filter(r=>score(r.residual)>r.appetite);losses=losses.filter(l=>risks.some(r=>r.id===l.risk));}
 else if(kind==='losses'){const from=current.params.get('from')||addDays(S.asOf,1-scopePeriod()),to=current.params.get('to')||S.asOf;losses=losses.filter(l=>l.date>=from&&l.date<=to);risks=risks.filter(r=>losses.some(l=>l.risk===r.id));label=`Loss occurrences · ${date(from)}–${date(to)}`;}
 else if(kind==='actions'){label='Overdue actions';risks=[];losses=[];}
 return {label,risks,losses,kind,tasks:kind==='actions'?ixOpenTasks().filter(t=>t.due<S.asOf):ixOpenTasks().filter(t=>risks.some(r=>r.id===t.ref))};
}
function ixDetailView(){
 const d=ixDetailData(),t=scopeTotals(d.losses);
 const head=header(e(d.label),'Source records behind this insight. The selected scope is preserved.',link('Back to insights','reports')+' '+(d.kind==='actions'?'':btn('Export these loss rows','ix-detail-export')),'Insight drill-down')+ixContext();
 if(d.kind==='actions')return head+panel('Actions requiring attention','Existing work records, not a duplicated reporting queue.',table(['Action','Owner','Due',''],d.tasks.map(x=>({cells:[e(x.title),e(x.owner),date(x.due),uxWorkAction(x)]}))));
 const metrics=metricRow([metric('Current risks',d.risks.length,'Source population for this view','risk'),metric('Gross loss',ngn(t.gross),'Occurrences in the selected loss window','chart'),metric('Recovered',ngn(t.recovered),'Received through the snapshot','refresh'),metric('Net loss',ngn(t.net),'Gross less recoveries','chart')]);
 const rows=d.losses.map(l=>({cells:[`<strong>${e(l.title)}</strong><small>${l.id} · ${l.type}</small>`,`${date(l.date)}<small>${e(orgName(l.orgScopeId))}</small>`,ngn(l.gross),ngn(recoveries(l)),ngn(l.gross-recoveries(l)),link('Open event','loss?id='+l.id,'small')]}));
 return head+metrics+panel('Risk records','Current accepted state; not a historical rating trend.',ixRiskTable(d.risks))+panel('Linked loss records','Each event appears once. Amounts are integer kobo in the export.',table(['Event','Occurred / location','Gross','Recovered','Net',''],rows));
}
const IX_SECTIONS=[['risks','Risk appetite'],['losses','Loss reconciliation'],['kri','Branch KRI returns'],['actions','Actions & accountability'],['assurance','Program assurance']];
function ixFrozenBody(p){const x=p.snapshot,sections=p.sections,parts=[];
 parts.push(`<div class="ix-pack-context"><strong>${e(x.organization)} · ${e(x.scope.label)}</strong><p>Posture ${date(x.asOf)} · loss occurrences ${date(x.periods.loss.from)}–${date(x.periods.loss.to)} · KRI ${ixMonthName(x.periods.kri.month)}</p><small>Source data captured ${e(recTimestamp(x.generatedAt))}. This is a fixed local snapshot.</small></div>`);
 if(p.commentary)parts.push(panel('Management commentary','Entered by the report author, not generated advice.',`<div class="pad" style="white-space:pre-wrap">${e(p.commentary)}</div>`));
 if(sections.includes('risks'))parts.push(panel('Risk appetite',`${x.risk.aboveAppetite} of ${x.risk.total} registered risks exceed their current appetite.`,table(['Risk','Residual','Appetite','Owner'],x.sourceRecords.risks.map(r=>({cells:[e(r.title),score(r.residual),r.appetite,e(r.owner)]})))));
 if(sections.includes('losses'))parts.push(panel('Recorded loss reconciliation',`NGN · ${x.losses.events} actual loss events and ${x.losses.nearMisses} near misses.`,table(['Gross','Recovered through snapshot','Net'],[{cells:[ngn(x.losses.gross),ngn(x.losses.recoveries),ngn(x.losses.net)]}])));
 if(sections.includes('kri'))parts.push(panel('Branch KRI reporting',`${x.kri.approved}/${x.kri.expected} returns approved; ${x.kri.known}/${x.kri.expectedValues} values known; ${x.kri.breaches} underlying unit-metric breaches.`,table(['Metric','Observed aggregate','Known / expected','Unit breaches'],x.kri.consolidation.map(m=>({cells:[e(m.name),m.value===null?'—':m.aggregation==='ratio-of-sums'?m.value.toFixed(3)+'%':num(m.value),`${m.observed}/${m.expected}`,m.breaches]})))));
 if(sections.includes('actions'))parts.push(panel('Open actions',`${x.actions.overdue} overdue of ${x.actions.open} open.`,table(['Action','Owner','Due'],x.sourceRecords.actions.map(t=>({cells:[e(t.title),e(t.owner),date(t.due)]})))));
 if(sections.includes('assurance'))parts.push(panel('Program assurance','Outcomes retain their actual assessment target.',table(['Program / target','Kind','Coverage','Satisfied'],x.programs.flatMap(p=>p.targets.map(t=>({cells:[`${e(p.name)}<small>${e(t.name)}</small>`,e(p.type),`${t.reviewed}/${t.all}`,`${t.pass}/${t.all}`]}))))));
 parts.push(panel('Limitations and interpretation','Read with the figures, not hidden in an appendix.',`<div class="pad">${x.limitations.map(s=>`<p>${e(s)}</p>`).join('')}</div>`));return `<article class="ix-frozen-pack">${parts.join('')}</article>`;
}
function ixNewReport(){S.reportDraft={step:1,name:`Risk review · ${selectedScope()?orgNode(selectedScope()).name:'Meridian Bank'}`,audience:'Management risk committee',sections:IX_SECTIONS.map(s=>s[0]),commentary:'',snapshot:clone(reportData())};save();go('report-builder');}
function ixReportBuilder(){const d=S.reportDraft;if(!d)return header('Build a report','Choose an audience, confirm the captured scope and publish a fixed snapshot.')+empty('No report in preparation','Open insights at your intended scope and start a report.',btn('Start report','ix-new-report','','primary'));let body='';
 if(d.step===1)body=`<h2>Who will use this report?</h2><p>Choose the relevant sections. The audience label does not change the underlying calculations.</p><div class="field-grid">${input('name','Report title',d.name,'text','data-ix-report-draft="name"')}${select('audience','Audience',['Board risk committee','Management risk committee','Branch management','Risk analyst'],d.audience,'data-ix-report-draft="audience"')}</div><h3 class="mt16">Report sections</h3><div class="ix-population">${IX_SECTIONS.map(([id,label])=>`<label class="checkbox-row"><input type="checkbox" data-ix-report-section="${id}" ${d.sections.includes(id)?'checked':''}>${label}</label>`).join('')}</div>`;
 if(d.step===2)body=`<h2>Confirm scope, periods and interpretation</h2><p>The source snapshot was captured when you started this report. Changing navigation scope does not change it.</p><div class="ix-confidence"><div><span>Scope</span><strong>${e(d.snapshot.scope.label)}</strong></div><div><span>Loss occurrence window</span><strong>${date(d.snapshot.periods.loss.from)}–${date(d.snapshot.periods.loss.to)}</strong></div><div><span>KRI month</span><strong>${ixMonthName(d.snapshot.periods.kri.month)}</strong></div><div><span>Known KRI values</span><strong>${d.snapshot.kri.known}/${d.snapshot.kri.expectedValues}</strong></div></div>${area('commentary','Management commentary / decisions required',d.commentary,'data-ix-report-draft="commentary" placeholder="State the decisions, owners and unresolved uncertainties…"')}${notice('The report includes data-quality limitations automatically. It is a local management snapshot, not a regulatory submission.','mini')}`;
 if(d.step===3)body=`<h2>Preview the report</h2><p>${e(d.name)} · ${e(d.audience)}. Publishing freezes the snapshot and commentary in the local demo.</p>${ixFrozenBody(d)}`;
 return header('Build management report','Audience → scope & commentary → preview and publish.',link('Exit builder','reports?view=library'),'Report preparation')+ixWizardSteps(['Audience & sections','Scope & commentary','Preview'],d.step,'ix-report-step')+`<section class="panel ix-wizard"><div class="pad">${body}<div id="ix-report-error" role="alert"></div></div><footer>${d.step>1?btn('Back','ix-report-step',`data-step="${d.step-1}"`):link('Cancel','reports')}<span>Step ${d.step} of 3</span>${d.step<3?btn('Continue '+icon('arrow'),'ix-report-step',`data-step="${d.step+1}"`,'primary'):btn('Publish snapshot','ix-publish-report','','primary')}</footer></section>`;
}
function ixReportPackView(){const p=S.reportPacks.find(p=>p.id===current.params.get('id'));if(!p)return header('Report snapshot','Frozen source data and commentary.')+empty('Report not found','Open an existing snapshot or build one.',link('Saved reports','reports?view=library'));return header(e(p.name),`${e(p.audience)} · ${p.id}`,link('Saved reports','reports?view=library')+' '+btn('Export snapshot','ix-export-pack',`data-id="${p.id}"`)+' '+btn('Print report','print','','primary'),'Published management report')+notice('Historical snapshot: the captured scope shown below is authoritative. Top-navigation changes do not recalculate this published report.','mini')+ixFrozenBody(p);}
function ixExportKri(){const c=ixCycle(),rows=[];for(const u of ixExpected(c)){const a=ixAccepted(c,u);if(!a)continue;for(const m of c.metrics){const v=a.values[m.id]||{};rows.push([c.id,c.period,c.definitionVersion,u,orgName(u),m.id,m.name,ixMetricValue(m,v),m.unit,v.numerator??'',v.denominator??'',ixBand(m,v),v.sourceRef||'',v.missing?v.reason:'',a.id,a.reviewedBy,a.reviewedAt]);}}exportCSV('clearsight-accepted-branch-kri.csv',['cycle_id','month','definition_version','scope_id','location','metric_id','metric','value','unit','numerator','denominator','condition','source_ref','missing_reason','submission_id','reviewer','approved_date'],rows);}
Object.assign(actions,{
 'ix-start-return':el=>{const c=ixCycle(el.dataset.cycle),u=el.dataset.unit;requireValue(c.population.includes(u)&&ixMatch(u),'Reporting unit is outside this cycle or scope.');const id=ixReturnKey(c.id,u);if(!S.branchKri.returns[id])S.branchKri.returns[id]={id,cycle:c.id,unit:u,owner:c.owners[u],status:'Draft',values:{},revision:0,submissions:[],history:[{date:S.asOf,text:'Working return started.',actor:c.owners[u]}]};save();go(ixReturnRoute(id));},
 'ix-return-sample':()=>{const r=ixCurrentReturn();requireValue(r&&['Draft','Changes requested'].includes(r.status)&&ixMatch(r.unit),'This return is locked or out of scope.');r.values={reconciliation:{value:0,sourceRef:'SYNTHETIC-RECON-001',comment:'Explicit nil exception count.'},complaints:{value:6,sourceRef:'SYNTHETIC-COMPLAINTS-001',comment:'Backlog after a service disruption; owner will resolve the aged cases.'},failedPayments:{numerator:8,denominator:2000,sourceRef:'SYNTHETIC-PAYMENTS-001',comment:''}};save();render();toast('Loaded clearly labelled synthetic example values.');},
 'ix-return-save':()=>{save();toast('Working return saved locally. It is not included in accepted reporting.');},
 'ix-return-submit':ixSubmitReturn,
 'ix-new-cycle':()=>{if(S.branchKri.draftCycle)go('kri-cycle');else ixNewCycle();},
 'ix-cycle-step':el=>{const d=S.branchKri.draftCycle,step=Number(el.dataset.step);requireValue(d&&[1,2,3].includes(step),'Choose a valid setup step.');if(step>d.step){const issues=ixCycleIssues(d).filter(msg=>step===2?/Name the|reporting month/.test(msg):true);if(issues.length){$('#ix-cycle-error').innerHTML=notice(issues.map(e).join('<br>'),'warning');return;}}d.step=step;save();render();},
 'ix-create-cycle':()=>{const d=S.branchKri.draftCycle,issues=ixCycleIssues(d);if(issues.length){$('#ix-cycle-error').innerHTML=notice(issues.map(e).join('<br>'),'warning');return;}const id=uid('KRC'),last=new Date(Date.UTC(Number(d.period.slice(0,4)),Number(d.period.slice(5,7)),0)).toISOString().slice(0,10);S.branchKri.cycles.unshift({id,period:d.period,title:d.name+' · '+ixMonthName(d.period),population:[...new Set(d.population)],metrics:clone(IX_METRICS),definitionVersion:'BRANCH-OPS/1.0',reviewer:d.reviewer,owners:Object.fromEntries(d.population.map(u=>[u,d.owner])),programId:d.programId,due:addDays(last,10)});S.insightCycle=id;S.branchKri.draftCycle=null;audit('Created reporting cycle with frozen unit population',id);go('kri-returns');},
 'ix-kri-branch':el=>{scopeChange('branch',el.dataset.id);go('kri-returns');},
 'ix-export-kri':ixExportKri,
 'ix-detail-export':()=>{const d=ixDetailData();exportCSV('clearsight-insight-source-losses.csv',['id','title','scope','date','gross_kobo','recovered_kobo','net_kobo'],d.losses.map(l=>[l.id,l.title,l.orgScopeId,l.date,l.gross,recoveries(l),l.gross-recoveries(l)]));},
 'ix-save-view':()=>{const config={view:S.insightView,scope:clone(S.scope),scopeLabel:scopeLabel(),lossPeriod:scopePeriod(),cycle:ixCycle().id,group:current.params.get('group')||''};openDialog('Save this live view','Scope and periods are remembered; numbers update with local records.',input('name','View name',`${selectedScope()?orgNode(selectedScope()).name:'Bank'} · ${IX_VIEWS.find(v=>v[1]===S.insightView)?.[0]||'Insights'}`,'text','required maxlength="100"'),'Save view',form=>{const name=values(form).name.trim();requireValue(name.length>2,'Enter a useful view name.');S.savedInsightViews.unshift({id:uid('VIEW'),name,...config});save();toast('Saved a live view, not a frozen report.');});},
 'ix-open-view':el=>{const v=S.savedInsightViews.find(v=>v.id===el.dataset.id);requireValue(v,'Saved view not found.');S.scope=clone(v.scope);S.lossPeriod=v.lossPeriod;S.insightCycle=v.cycle;S.insightView=v.view;save();go('reports?view='+v.view+'&period='+v.lossPeriod+(v.group?'&group='+encodeURIComponent(v.group):''));},
 'ix-new-report':()=>{if(S.reportDraft)go('report-builder');else ixNewReport();},
 'ix-report-step':el=>{const d=S.reportDraft,step=Number(el.dataset.step);requireValue(d&&[1,2,3].includes(step),'Choose a valid report step.');if(step>d.step&&(!d.name.trim()||!d.sections.length)){$('#ix-report-error').innerHTML=notice('Name the report and choose at least one section.','warning');return;}d.step=step;save();render();},
 'ix-publish-report':()=>{const d=S.reportDraft;requireValue(d&&d.name.trim().length>2,'Name the report.');requireValue(d.sections.length&&d.sections.every(id=>IX_SECTIONS.some(s=>s[0]===id)),'Choose at least one valid report section.');const p={...clone(d),id:uid('RPT'),created:new Date().toISOString()};delete p.step;S.reportPacks.unshift(p);S.reportDraft=null;audit('Published a frozen management report',p.id);go('report-pack?id='+p.id);},
 'ix-export-pack':el=>{const p=S.reportPacks.find(p=>p.id===el.dataset.id);requireValue(p,'Report not found.');download('clearsight-'+p.id+'.json',JSON.stringify(p,null,2));}
});
document.addEventListener('input',ev=>{const el=ev.target;
 if(el.matches('[data-kri-metric]')&&el.dataset.kriPart!=='missing'){
  const r=ixCurrentReturn();if(!r||!['Draft','Changes requested'].includes(r.status)||!ixMatch(r.unit))return;const id=el.dataset.kriMetric,part=el.dataset.kriPart;r.values[id]??={};r.values[id][part]=['value','numerator','denominator'].includes(part)?el.value===''?null:Number(el.value):el.value;
  const badge=$('#kri-band-'+id);if(badge)badge.innerHTML=pill(ixBand(ixDefinition(ixCycle(r.cycle),id),r.values[id]));save();
 }
 if(el.matches('[data-ix-cycle-draft]')){S.branchKri.draftCycle[el.dataset.ixCycleDraft]=el.value;save();}
 if(el.matches('[data-ix-report-draft]')){S.reportDraft[el.dataset.ixReportDraft]=el.value;save();}
});
document.addEventListener('change',ev=>{const el=ev.target;
 if(el.matches('[data-ix-cycle]')){S.insightCycle=el.value;save();render();}
 if(el.matches('[data-ix-group]'))go('reports?view=drivers&group='+encodeURIComponent(el.value));
 if(el.matches('[data-ix-cycle-draft]')){S.branchKri.draftCycle[el.dataset.ixCycleDraft]=el.value;save();}
 if(el.matches('[data-ix-report-draft]')){S.reportDraft[el.dataset.ixReportDraft]=el.value;save();}
 if(el.matches('[data-ix-population]')){const d=S.branchKri.draftCycle;d.population=el.checked?[...new Set([...d.population,el.dataset.ixPopulation])]:d.population.filter(u=>u!==el.dataset.ixPopulation);save();}
 if(el.matches('[data-ix-report-section]')){const d=S.reportDraft;d.sections=el.checked?[...new Set([...d.sections,el.dataset.ixReportSection])]:d.sections.filter(s=>s!==el.dataset.ixReportSection);save();}
 if(el.matches('[data-kri-part="missing"]')){const r=ixCurrentReturn();if(!r||!['Draft','Changes requested'].includes(r.status)||!ixMatch(r.unit))return;r.values[el.dataset.kriMetric]??={};r.values[el.dataset.kriMetric].missing=el.checked;save();render();}
});
document.addEventListener('submit',ev=>{if(!ev.target.matches('[data-ix-submit]'))return;ev.preventDefault();try{if(ev.target.dataset.ixSubmit==='kri-review')ixReviewReturn(ev.target);}catch(err){$('.form-error',ev.target).textContent=err.message;}});
// The review queue composes existing Work; observations do not create another inbox.
const ixPriorWorkItems=workItems;
workItems=function(){const items=ixPriorWorkItems();if(!S.branchKri)return items;for(const r of Object.values(S.branchKri.returns))if(r.status==='Submitted'&&ixMatch(r.unit)){const c=ixCycle(r.cycle);items.push({id:'KRI-REVIEW-'+r.id,title:'Review branch KRI return · '+orgName(r.unit)+' · '+ixMonthName(c.period),kind:'KRI return review',owner:c.reviewer,due:c.due,status:'Open',orgScopeId:r.unit,ref:r.id,source:'branch-kri',route:ixReturnRoute(r.id)});}return items;};
Object.assign(window.CS_JOURNEYS,{'kri-returns':ixKriReturnsView,'kri-return':ixReturnView,'kri-cycle':ixCycleView,'insight-detail':ixDetailView,'report-builder':ixReportBuilder,'report-pack':ixReportPackView});
Object.assign(window.CS_JOURNEY_GROUPS,{'kri-returns':'risks','kri-return':'risks','kri-cycle':'risks','insight-detail':'reports','report-builder':'reports','report-pack':'reports'});
Object.assign(titles,{'kri-returns':'Branch KRI returns','kri-return':'Branch KRI return','kri-cycle':'Create KRI reporting cycle','insight-detail':'Insight source records','report-builder':'Build management report','report-pack':'Published report snapshot'});
const ixPriorRender=render;
render=function(){ixInit();ixPriorRender();if(['home','risks'].includes(current.name))$('.page-head .actions')?.insertAdjacentHTML('afterbegin',link(icon('chart')+' Risk insights','reports','quiet'));if(current.name==='indicators')$('.page-head .actions')?.insertAdjacentHTML('afterbegin',link('Monthly branch returns','kri-returns'));if(current.name==='kri-returns'&&S.branchKri.draftCycle)$('.page-footer')?.insertAdjacentHTML('beforebegin',notice('An unfinished reporting cycle is saved. '+link('Resume setup','kri-cycle','small')));if(current.name==='reports'&&S.reportDraft&&current.params.get('view')==='library')$('.page-footer')?.insertAdjacentHTML('beforebegin',notice('A management report is in preparation. '+link('Resume report','report-builder','small')));};
window.CLEAR_SIGHT_INSIGHTS=Object.freeze({version:'2.5-demo',getKri:()=>clone(S.branchKri),getKriStats:()=>clone(ixKriStats()),getReport:()=>clone(reportData()),getScope:()=>clone(S.scope),getDetail:()=>clone(ixDetailData())});
// Initial render is owned by documents.js.
